// BN's mutable lab_basement (overmap_mutable/lab.json) as generated by the overmap_mutable port
// (src/world/overmap/mutable.ts): escape cells, train depots, the lab_escape start, and the
// promise that genVersion 1 worlds still generate exactly as before.
import { describe, expect, it } from 'vitest';
import { hashString, Rng } from '../src/core/rng';
import { CHUNK, MIN_Z } from '../src/world/coords';
import { CLASSIC_LAB_SPECIAL, LAB_BASEMENT_TYPES, Overmap, REGION, WORLDGEN_VERSION, genZRange } from '../src/world/overmap/overmap';
import { MutableSpecial, sampleDist } from '../src/world/overmap/mutable';
import { LINE_S } from '../src/world/overmap/oter';
import { WorldGenerator } from '../src/world/worldgen';
import { findStart } from '../src/progression/placement';
import { loadNodeData, makeMap } from '../tools/lib/node_data';

const { game: data, wg } = loadNodeData();

/** Hash of every oter id (and owning special) in one region, z 0..-5. */
function regionHash(ov: Overmap, rx: number, ry: number): string {
  const parts: string[] = [];
  for (let z = 0; z >= -5; z--)
    for (let y = ry * REGION; y < (ry + 1) * REGION; y++)
      for (let x = rx * REGION; x < (rx + 1) * REGION; x++) {
        const o = ov.omtAt(x, y, z);
        parts.push(o.special ? `${o.id}@${o.special.def}` : o.id);
      }
  return hashString(parts.join('|')).toString(16);
}

describe('genVersion 1 is frozen', () => {
  it('regions hash the same as before the lab_basement port', () => {
    const got: Record<string, string> = {};
    for (const [seed, rx, ry] of [[1, 0, 0], [1, 1, 0], [1, 0, -1], [42, 0, 0], [743667900, -1, 1]] as const) {
      got[`${seed}:${rx},${ry}`] = regionHash(new Overmap(seed, wg.overmap, 1), rx, ry);
    }
    // Recorded from the overmap generator before the genVersion 2 lab_basement port.
    expect(got).toEqual({ '1:0,0': 'c3f2c575', '1:1,0': 'a7193272', '1:0,-1': '7361569a', '42:0,0': 'bd20071', '743667900:-1,1': 'f19b164e' });
  });
});

// ------------------------------------------------------------------------------------------
// genVersion 2: the mutable lab_basement


interface LabOmt { x: number; y: number; z: number; type: string }
/** Every OMT of a classic lab's basement (the special's uid), z -1 down to the map's floor. */
function labOmts(ov: Overmap, sp: { x: number; y: number; uid: number }): LabOmt[] {
  const out: LabOmt[] = [];
  for (let z = -1; z >= MIN_Z; z--)
    for (let dy = -14; dy <= 14; dy++)
      for (let dx = -14; dx <= 14; dx++) {
        const o = ov.omtAt(sp.x + dx, sp.y + dy, z);
        if (o.special?.uid === sp.uid) out.push({ x: sp.x + dx, y: sp.y + dy, z, type: o.type });
      }
  return out;
}
const regionOf = (ov: Overmap, rx: number, ry: number) => (ov as any).region(rx, ry) as { specials: { def: string; uid: number; x: number; y: number }[]; connectionRequests: { x: number; y: number; z: number; connection: string; uid: number }[]; x0: number; y0: number };

describe('BN lab_basement (genVersion 2)', () => {
  it('is the latest generation', () => expect(WORLDGEN_VERSION).toBeGreaterThanOrEqual(2));

  it('int distributions sample like BN (poisson mean, chance x scale, fixed range)', () => {
    const rng = new Rng(5);
    let sum = 0, hits = 0;
    for (let i = 0; i < 4000; i++) sum += sampleDist({ poisson: 4 }, 4, rng);
    for (let i = 0; i < 4000; i++) hits += sampleDist({ chance: 0.2 }, 4, rng);
    expect(sum / 4000).toBeGreaterThan(15.5);
    expect(sum / 4000).toBeLessThan(16.5);
    // BN chance_distribution: (0.2 * 4) >= rng_float(0, 1), i.e. 80%
    expect(hits / 4000).toBeGreaterThan(0.77);
    expect(hits / 4000).toBeLessThan(0.83);
    expect(sampleDist([4, 4], 1, rng)).toBe(4);
  });

  // Many labs from fixed seeds: the BN rules hold for every one, and the escape chunk shows up
  // about as often as BN's 0.2 x size 4 says.
  // connection requests are region-local; converted to global here
  const labs: { ov: Overmap; sp: { x: number; y: number; uid: number }; omts: LabOmt[]; reqs: { x: number; y: number; z: number; connection: string }[] }[] = [];
  for (let seed = 1; seed <= 12; seed++) {
    const ov = new Overmap(seed, wg.overmap);
    for (const [rx, ry] of [[0, 0], [1, 0], [0, 1], [-1, -1]]) {
      const r = regionOf(ov, rx, ry);
      for (const sp of r.specials.filter((s) => s.def === CLASSIC_LAB_SPECIAL)) labs.push({ ov, sp, omts: labOmts(ov, sp), reqs: r.connectionRequests.filter((q) => q.uid === sp.uid).map((q) => ({ ...q, x: q.x + r.x0, y: q.y + r.y0 })) });
    }
  }

  it('grows from a lab_core under the entrance, every lab_stairs over a lab_core, finale at the bottom', () => {
    expect(labs.length).toBeGreaterThan(30);
    let finales = 0;
    for (const { ov, sp, omts } of labs) {
      expect(ov.omtAt(sp.x, sp.y, -1).type).toBe('lab_core');
      const at = new Map(omts.map((o) => [`${o.x},${o.y},${o.z}`, o.type]));
      for (const o of omts) {
        expect(LAB_BASEMENT_TYPES as readonly string[]).toContain(o.type);
        if (o.type === 'lab_stairs') expect(at.get(`${o.x},${o.y},${o.z - 1}`), `${o.x},${o.y},${o.z}`).toBe('lab_core');
      }
      const bottom = Math.min(...omts.map((o) => o.z));
      // genVersion 3 grows to BN's -10 (tests/world_depth.test.ts), 2 stopped at -7
      expect(bottom).toBeGreaterThanOrEqual(genZRange(ov.genVersion)[0]);
      if (omts.some((o) => o.type === 'lab_finale' && o.z === bottom)) finales++;
    }
    expect(finales / labs.length).toBeGreaterThan(0.9);
  });

  it('places the escape cells chunk ~80% of the time, below z-4, cells walled off but for the entrance', () => {
    let n = 0;
    for (const { omts } of labs) {
      const at = new Map(omts.map((o) => [`${o.x},${o.y},${o.z}`, o.type]));
      const cells = omts.filter((o) => o.type === 'lab_escape_cells');
      expect(cells.length).toBeLessThanOrEqual(1);
      for (const c of cells) {
        n++;
        expect(c.z).toBeLessThanOrEqual(-4);
        // never rotated: the entrance is always south of the cells
        expect(at.get(`${c.x},${c.y + 1},${c.z}`)).toBe('lab_escape_entrance');
        // BN joins: the cells reject lab neighbours to the north, east and west
        for (const [dx, dy] of [[0, -1], [1, 0], [-1, 0]]) expect(at.get(`${c.x + dx},${c.y + dy},${c.z}`)).toBeUndefined();
      }
    }
    expect(n / labs.length).toBeGreaterThan(0.65);
    expect(n / labs.length).toBeLessThan(0.95);
  });

  it('puts a train depot at z-2 and z-4 asking for a subway_tunnel from its open side', () => {
    let depots = 0;
    for (const { omts, reqs } of labs) {
      const at = new Map(omts.map((o) => [`${o.x},${o.y},${o.z}`, o.type]));
      const ds = omts.filter((o) => o.type === 'lab_train_depot');
      expect(ds.every((d) => d.z === -2 || d.z === -4)).toBe(true);
      depots += ds.length;
      // one request per depot, on an OMT next to it that the lab left free
      expect(reqs.filter((q) => q.connection === 'subway_tunnel').length).toBe(ds.length);
      for (const q of reqs) {
        expect(q.connection).toBe('subway_tunnel');
        expect(at.has(`${q.x},${q.y},${q.z}`)).toBe(false);
        expect([[0, 1], [0, -1], [1, 0], [-1, 0]].some(([dx, dy]) => at.get(`${q.x + dx},${q.y + dy},${q.z}`) === 'lab_train_depot')).toBe(true);
      }
    }
    // BN: chance 1 x size 4, so a depot wherever one fits; both levels nearly always have room
    expect(depots / labs.length).toBeGreaterThan(1.7);
  });

  it('the start region classic lab always has escape cells', () => {
    for (const seed of [1, 2, 3, 7, 42, 99, 743667900]) {
      const ov = new Overmap(seed, wg.overmap);
      const hit = ov.findUnderground('lab_escape_cells', { x: 0, y: 0 }, 0);
      expect(hit, `seed ${seed}`).toBeDefined();
    }
  });

  it('the compiled special matches lab.json', () => {
    const m = new MutableSpecial(wg.overmap.mutables!.lab_basement);
    expect(m.def.root).toBe('lab_core');
    expect(m.def.overmaps.lab_train_depot.connections).toEqual({ north: 'subway_tunnel' });
  });
});

function world(seed: number) {
  const map = makeMap(data, seed);
  const gen = new WorldGenerator(seed, wg, data);
  gen.stats.quiet = true;
  map.generator = gen;
  const start = gen.findStartLocation('shelter', map);
  return { map, gen, start };
}

describe('lab escape cells and train depot chunks', () => {
  it('the lab_escape start puts you in an empty experiment cell, walled in, below z-4', () => {
    for (const seed of [1, 7, 42]) {
      const { map, gen, start } = world(seed);
      const spot = findStart({ map, overmap: gen.overmap }, 'lab_escape', { x: start.omx, y: start.omy })!;
      expect(spot, `seed ${seed}`).toBeTruthy();
      expect(spot.z).toBeLessThanOrEqual(-4);
      const omt = gen.overmap.omtAt(Math.floor(spot.x / CHUNK), Math.floor(spot.y / CHUNK), spot.z);
      expect(omt.type).toBe('lab_escape_cells');
      expect(map.chunk(Math.floor(spot.x / CHUNK), Math.floor(spot.y / CHUNK), spot.z)!.omt?.source).toBe('json');
      expect(map.passable(spot.x, spot.y, spot.z)).toBe(true);
      // BN's cells are the 3-wide rooms in rows 17-22 of the OMT
      const ly = spot.y - Math.floor(spot.y / CHUNK) * CHUNK;
      expect(ly).toBeGreaterThanOrEqual(17);
      expect(ly).toBeLessThanOrEqual(22);
      // shut in: flood fill inside the OMT stays small (a cell, not the corridor)
      const seen = new Set<string>([`${spot.x},${spot.y}`]);
      const stack = [[spot.x, spot.y]];
      const cx0 = Math.floor(spot.x / CHUNK) * CHUNK, cy0 = Math.floor(spot.y / CHUNK) * CHUNK;
      while (stack.length) {
        const [x, y] = stack.pop()!;
        for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const nx = x + dx, ny = y + dy;
          if (nx < cx0 || ny < cy0 || nx >= cx0 + CHUNK || ny >= cy0 + CHUNK || seen.has(`${nx},${ny}`) || !map.passable(nx, ny, spot.z)) continue;
          seen.add(`${nx},${ny}`);
          stack.push([nx, ny]);
        }
      }
      expect(seen.size).toBeLessThanOrEqual(30);
      expect(spot.where).toMatch(/cell/);
    }
  });

  it('a train depot opens its tunnel only towards a subway that runs up to it', () => {
    const ov = new Overmap(1, wg.overmap);
    const hit = ov.findUnderground('lab_train_depot', { x: 0, y: 0 }, 0)!;
    expect(hit).toBeDefined();
    // subway: 'real' leaves what the overmap's subway builder laid (it joins the depot's request);
    // 'none' clears the tunnels next to the depot; 'fixture' lays one north of it running south into it.
    const rails = (seed: number, subway: 'real' | 'none' | 'fixture') => {
      const gen = new WorldGenerator(1, wg, data);
      gen.stats.quiet = true;
      if (subway !== 'real') {
        const r = (gen.overmap as any).region(Math.floor(hit.x / REGION), Math.floor(hit.y / REGION));
        const key = (dx: number, dy: number) => hit.z * REGION * REGION + (hit.y + dy - r.y0) * REGION + hit.x + dx - r.x0;
        // The depot rotates with its Lab, so the builder's tunnel may come in from any side.
        const sub = (gen.overmap as any).intern('subway');
        for (const [dx, dy] of [[0, -1], [1, 0], [0, 1], [-1, 0]]) if (r.layers.get(key(dx, dy))?.t === sub) r.layers.delete(key(dx, dy));
        if (subway === 'fixture') r.layers.set(key(0, -1), { t: sub, rot: 0, line: LINE_S | 1, sp: 0 });
      }
      const map = makeMap(data, seed);
      map.generator = gen;
      const ch = map.chunk(hit.x, hit.y, hit.z)!;
      expect(ch.omt?.source).toBe('json');
      return Array.from(ch.ter).filter((t) => /railroad_track|buffer_stop/.test(map.terrain.get(t).id)).length;
    };
    expect(rails(1, 'none')).toBe(0);
    expect(rails(1, 'fixture')).toBeGreaterThan(20);
    expect(rails(1, 'real'), 'the subway builder connects the depot').toBeGreaterThan(20);
  });
});
